fn solve(t: Vec<char>) -> Vec<char> {
    // Input is assumed non-empty, but the logic works for empty as well.
    let n = t.len();
    let mut out: Vec<char> = Vec::with_capacity(n);

    // i elements have been processed; n - i remain (a strictly decreasing measure).
    let mut i: usize = 0;
    while i < n {
        out.push(t[i]); // preserves: out[k] == t[k] for all k < out.len()
        i += 1;         // decreases remaining measure: (n - i)
    }

    debug_assert_eq!(out.len(), n);
    out
}